package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class ContextAccuracyTest {
 static String rounded(int n,int p){int d=p==1?100:p==2?10:1;return BigDecimal.valueOf(n/d+(2*(n%d)>=d?1:0),p).toPlainString();}
 @Test public void normalPlacementFreshSupplyAndVariableCorrectPosition(){var pack=GlobalCurriculum.packs("GB").stream().filter(p->p.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(ContextAccuracy.ID,6));assertFalse(pack.inGrade(ContextAccuracy.ID,5));assertFalse(Curriculum.inCurriculum(Catalog.get(ContextAccuracy.ID),2022));Generator gen=new Generator(new Random(201));List<String> recent=new ArrayList<>();Set<String> kinds=new HashSet<>();Set<Integer> positions=new HashSet<>();assertTrue(ContextAccuracy.count()>100);for(int i=0;i<300;i++){Question q=gen.next(ContextAccuracy.ID,recent,i%2==0,GlobalCurriculum.limits(pack.id,ContextAccuracy.ID,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=ContextAccuracy.read(q);assertNotNull(v);kinds.add(v.unit()+v.places());String expected=rounded(v.amount().movePointRight(3).intValueExact(),v.places());assertEquals(3,q.choices.size());assertEquals(3,new HashSet<>(q.choices).size());positions.add(q.choices.indexOf(expected));q.answers=new String[]{"poison"};q.expression="poison";q.choiceLabels=Map.of();Checker c=new Checker();for(String value:q.choices)assertEquals(value.equals(expected)?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(value)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("999")).status);}assertEquals(Set.of("m1","m2","m3","L1","L2","L3"),kinds);assertEquals(Set.of(0,1,2),positions);}
 @Test public void publicAccuracyAndNineBlankHelpSteps(){for(String unit:List.of("m","L"))for(int p=1;p<=3;p++)for(int n:List.of(1234,1994,99994)){Question q=ContextAccuracy.make(n,p,unit);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(9,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));BigDecimal original=BigDecimal.valueOf(n,3),u=BigDecimal.ONE.movePointLeft(p),base=original.divideToIntegralValue(u).multiply(u);int digit=original.subtract(base).divideToIntegralValue(u.movePointLeft(1)).intValue();String[] values={""+p,original.toPlainString(),""+p,u.toPlainString(),""+digit,digit>=5?"raise":"keep",base.toPlainString(),digit>=5?u.toPlainString():"0",rounded(n,p)};for(int stage=0;stage<9;stage++){assertTrue("stage"+stage,h.step(stage).accepts(values[stage]));assertFalse(h.step(stage).before.matches(".*[0-9].*"));}assertFalse(h.step(0).accepts(""+(p%3+1)));q.prompt=q.prompt.replace("기록 단위:","기록:");assertNull(ContextAccuracy.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1.23")).status);}try{ContextAccuracy.make(1200,2,"m");fail();}catch(IllegalArgumentException expected){} }
}
